<template><section><header class="page-head"><div><p class="eyebrow">REPAIR CENTER</p><h2>报修管理</h2></div><el-button type="primary" @click="dialog=true">提交报修</el-button></header><div class="toolbar"><el-select v-model="status" placeholder="全部状态" clearable @change="load" style="width:180px"><el-option v-for="(t,k) in repairStatusText" :key="k" :label="t" :value="k"/></el-select></div><div class="repair-list"><RepairCard v-for="v in items" :key="v.id" :repair="v" :can-cancel="canCancel(v)" :cancelling="cancellingId===v.id" @cancel="cancel(v)" @open="open(v)"/><EmptyState v-if="!items.length"/></div>

<el-dialog v-model="dialog" title="提交报修工单"><el-form><el-input v-model="form.title" placeholder="报修标题"/><el-input v-model="form.description" type="textarea" placeholder="问题描述"/><el-select v-model="form.type"><el-option label="水电" value="水电"/><el-option label="家具" value="家具"/><el-option label="公共设施" value="公共设施"/><el-option label="其他" value="其他"/></el-select></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="submit">提交</el-button></template></el-dialog>

<el-dialog v-model="detailVisible" title="工单详情" width="560px" v-if="detail"><div class="detail-grid"><div><small>工单编号</small><b>#{{detail.id}}</b></div><div><small>报修标题</small><b>{{detail.title}}</b></div><div class="span2"><small>问题描述</small><b>{{detail.description}}</b></div><div><small>报修类型</small><b>{{detail.type}}</b></div><div><small>当前状态</small><RepairStatusBadge :status="detail.status"/></div><div><small>报修业主</small><b>{{detail.user?.nickname||'业主'}}</b></div><div><small>处理人</small><b>{{detail.handler?.nickname||'暂未分派'}}</b></div><div><small>提交时间</small><b>{{new Date(detail.created_at).toLocaleString()}}</b></div><div><small>更新时间</small><b>{{new Date(detail.updated_at).toLocaleString()}}</b></div><div v-if="detail.status==='cancelled' && detail.cancelled_at" class="span2 cancel-box"><small>撤销时间</small><b>{{new Date(detail.cancelled_at).toLocaleString()}}（工单保留，不再计入待处理）</b></div></div><el-alert v-if="detail.status==='cancelled'" type="info" :closable="false" show-icon title="该工单已被业主撤销，不能再分派或推进。" style="margin-top:14px"/><template #footer><el-button @click="detailVisible=false">关闭</el-button><el-button v-if="isStaff && detail.status!=='cancelled'" @click="assign(detail)" :loading="actingId===detail.id">分派处理人</el-button><el-button v-if="isStaff && detail.status!=='cancelled' && detail.status!=='done' && detail.status!=='closed'" type="primary" @click="advance(detail)" :loading="actingId===detail.id">推进进度</el-button><el-button v-if="canCancel(detail)" type="danger" @click="cancel(detail)" :loading="cancellingId===detail.id">撤销工单</el-button></template></el-dialog>
</section></template>

<script setup lang="ts">import{ref,onMounted}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{listRepairs,createRepair,cancelRepair,assignRepair,updateRepairStatus}from'../api/repair';import{getStaff}from'../api/user';import{repairStatusText,isOwnerCancellable}from'../constants/repair';import{authStore}from'../stores/authStore';import{useAuth}from'../hooks/useAuth';import type{Repair,RepairStatus,User}from'../types';import RepairCard from'../components/common/RepairCard.vue';import EmptyState from'../components/common/EmptyState.vue';import RepairStatusBadge from'../components/common/RepairStatusBadge.vue';
const {isStaff}=useAuth();
const items=ref<Repair[]>([]),status=ref(''),dialog=ref(false),form=ref({title:'',description:'',type:'水电',images:''});
const detail=ref<Repair|null>(null),detailVisible=ref(false),cancellingId=ref(0),actingId=ref(0);

async function load(){items.value=await listRepairs(status.value)}
function canCancel(v:Repair){return authStore.user?.role==='resident'&&v.user_id===authStore.user.id&&isOwnerCancellable(v.status)}
function open(v:Repair){detail.value=v;detailVisible.value=true}
function syncBack(v:Repair){const i=items.value.findIndex(x=>x.id===v.id);if(i>=0)items.value[i]=v;if(detail.value?.id===v.id)detail.value=v}
async function submit(){try{await createRepair(form.value);ElMessage.success('报修工单已提交');dialog.value=false;form.value={title:'',description:'',type:'水电',images:''};await load()}catch(e){ElMessage.error((e as Error).message)}}
async function cancel(v:Repair){try{await ElMessageBox.confirm(`确认撤销工单“${v.title}”？撤销后工单保留并标记为已取消，且无法恢复。`,'业主撤销工单',{type:'warning',confirmButtonText:'确认撤销',cancelButtonText:'再想想'});cancellingId.value=v.id;const updated=await cancelRepair(v.id);syncBack(updated);ElMessage.success('报修工单已撤销');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}finally{cancellingId.value=0}}
async function assign(v:Repair){const staff:User[]=await getStaff();if(!staff.length){ElMessage.warning('暂无可分派的物业人员');return}const {value}=await ElMessageBox.prompt('选择处理人','分派处理人',{inputType:'text',inputPlaceholder:staff.map(s=>`${s.id}:${s.nickname}`).join('，'),inputValidator:(x)=>staff.some(s=>String(s.id)===String(x))||'请输入列表中的处理人编号'});actingId.value=v.id;try{const updated=await assignRepair(v.id,Number(value));syncBack(updated);ElMessage.success('已分派处理人');await load()}catch(e){ElMessage.error((e as Error).message)}finally{actingId.value=0}}
async function advance(v:Repair){const next:RepairStatus=v.status==='pending'?'assigned':v.status==='assigned'?'processing':v.status==='processing'?'done':'closed';actingId.value=v.id;try{const updated=await updateRepairStatus(v.id,next);syncBack(updated);ElMessage.success(`状态已更新为「${repairStatusText[next]}」`);await load()}catch(e){ElMessage.error((e as Error).message)}finally{actingId.value=0}}
onMounted(load)</script>
